"""Build the small test fixtures from a real v1 full-core PEARLSim step.

Run once from the repository root (needs the untracked v1 run directory):

    python tests/fixtures/make_fixtures.py

Source: ``gFHR_benchmark_1975/`` step 100 (equilibrium, 280 MWth), generated by
``v1-as-run``. Large files are trimmed; the expected reader outputs are computed
from the *full* source files, so tests on the trimmed copies are checked against
what the readers return on the real data. Source checksums are written to
``SOURCES.tsv``.
"""

import hashlib
import json
import os
import shutil
import sys

import numpy as np

REPO = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
SRC = os.path.join(REPO, "gFHR_benchmark_1975")
OUT = os.path.join(REPO, "tests", "fixtures", "equilibrium_step100")
RUN = "gFHR_equilibrium"
STEP = 100
N_BUMAT_MATERIALS = 6

sys.path.insert(0, REPO)
from pearlsim.core import Core  # noqa: E402
from pearlsim.ml_utilities import read_det_file  # noqa: E402
from pearlsim.group_definitions import ENERGY_GRID_3, HEIGHT_GRID_20, RADIUS_GRID_8  # noqa: E402
from pearlsim.results_processing import extract_lstm_input_features, read_res_file  # noqa: E402


def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def trim_bumat(src, dst, n_materials):
    """Keep the header and the first ``n_materials`` ``mat`` blocks."""
    kept = 0
    with open(src) as fin, open(dst, "w") as fout:
        for line in fin:
            if line.startswith("mat"):
                kept += 1
                if kept > n_materials:
                    break
            fout.write(line)


def strip_concentrations(src, dst):
    with open(src) as f:
        data = json.load(f)
    for entry in data.values():
        entry.pop("concentration", None)
        entry.pop("concentrations", None)
    with open(dst, "w") as f:
        json.dump(data, f, indent=1, sort_keys=True)


def bumat_summary(path):
    """Per-material nuclide count and total atom density, as parsed by Core.update_from_bumat."""
    core = Core(RUN)
    core.simulation_name = RUN
    cwd = os.getcwd()
    os.chdir(os.path.dirname(path))
    try:
        step = int(path.rsplit("bumat", 1)[1])
        core.update_from_bumat(0, iteration=STEP, step=step)
    finally:
        os.chdir(cwd)
    return {name: [len(m.concentrations), float(sum(m.concentrations.values()))]
            for name, m in core.materials.items()}


def main():
    os.makedirs(OUT, exist_ok=True)
    whole = [
        f"{RUN}_{STEP}.serpent_res.m",
        f"{RUN}_{STEP}.serpent_det0.m",
        f"{RUN}_{STEP}.serpent_det1.m",
        f"zone_map{STEP}.json",
        f"{RUN}_operating_{STEP}.json",
    ]
    stripped = [f"{RUN}_discharge_inventory{STEP}.json", f"{RUN}_discard_inventory{STEP}.json"]
    bumat = f"{RUN}_{STEP}.serpent.bumat1"

    with open(os.path.join(OUT, "SOURCES.tsv"), "w") as f:
        f.write("file\tsource_sha256\tsource_bytes\ttreatment\n")
        for name in whole:
            shutil.copyfile(os.path.join(SRC, name), os.path.join(OUT, name))
            f.write(f"{name}\t{sha256(os.path.join(SRC, name))}\t{os.path.getsize(os.path.join(SRC, name))}\tcopied\n")
        for name in stripped:
            strip_concentrations(os.path.join(SRC, name), os.path.join(OUT, name))
            f.write(f"{name}\t{sha256(os.path.join(SRC, name))}\t{os.path.getsize(os.path.join(SRC, name))}"
                    "\tconcentration fields removed\n")
        trim_bumat(os.path.join(SRC, bumat), os.path.join(OUT, bumat), N_BUMAT_MATERIALS)
        f.write(f"{bumat}\t{sha256(os.path.join(SRC, bumat))}\t{os.path.getsize(os.path.join(SRC, bumat))}"
                f"\tfirst {N_BUMAT_MATERIALS} mat blocks\n")

    # Expected values, computed from the full source files.
    keff, keff_unc = read_res_file(os.path.join(SRC, f"{RUN}_{STEP}.serpent_res.m"), "ANA_KEFF", burnup_step="all")
    meshes = read_det_file(
        os.path.join(SRC, f"{RUN}_{STEP}.serpent_det1.m"),
        meshes_to_read=["subzone_3group_flux", "subzone_power"],
        read_pebbles=False,
        mesh_grids_rze=[(RADIUS_GRID_8, HEIGHT_GRID_20, ENERGY_GRID_3), (RADIUS_GRID_8, HEIGHT_GRID_20, [0.0])],
    )
    features = extract_lstm_input_features(SRC, STEP, run_name=RUN, merge=True)
    full_bumat = bumat_summary(os.path.join(SRC, bumat))
    first = list(full_bumat)[:N_BUMAT_MATERIALS]

    expected = {
        "ana_keff": keff,
        "ana_keff_unc": keff_unc,
        "flux_mesh": np.asarray(meshes["subzone_3group_flux"]["data"]).tolist(),
        "power_mesh": np.asarray(meshes["subzone_power"]["data"]).tolist(),
        "lstm_input_features": {k: (v if isinstance(v, str) else float(v)) for k, v in features.items()},
        "bumat1_first_materials": {k: full_bumat[k] for k in first},
        "bumat1_material_count": len(full_bumat),
    }
    with open(os.path.join(OUT, "expected.json"), "w") as f:
        json.dump(expected, f, indent=1)
    total = sum(os.path.getsize(os.path.join(OUT, n)) for n in os.listdir(OUT))
    print(f"Wrote fixtures to {OUT} ({total / 1e6:.2f} MB)")


if __name__ == "__main__":
    main()
